package com.bank.firehose;

import org.apache.kafka.clients.producer.*;
import org.apache.kafka.common.serialization.StringSerializer;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class TxnFirehoseDemo {
    private static final Logger log = Logger.getLogger(TxnFirehoseDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Properties p = new Properties();
        p.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "broker1:9092");
        p.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        p.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());

        // ---- Throughput tuning (the five knobs) ----
        p.put(ProducerConfig.ACKS_CONFIG, "all");                       // durable
        p.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, "true");        // ordering kept at 5 in-flight
        p.put(ProducerConfig.BATCH_SIZE_CONFIG, 65_536);                // bigger batches
        p.put(ProducerConfig.LINGER_MS_CONFIG, 10);                     // let batches fill
        p.put(ProducerConfig.COMPRESSION_TYPE_CONFIG, "lz4");           // shrink the batch
        p.put(ProducerConfig.MAX_IN_FLIGHT_REQUESTS_PER_CONNECTION, 5); // pipelining
        p.put(ProducerConfig.BUFFER_MEMORY_CONFIG, 67_108_864);         // room to accumulate

        int total = 1_000_000;
        long start = System.currentTimeMillis();
        try (Producer<String, String> producer = new KafkaProducer<>(p)) {
            for (int i = 0; i < total; i++) {
                String account = (i % 2 == 0) ? "SAV2001" : "CUR3001";  // Rajesh / Priya
                TxnEvent event = new TxnEvent(account, new BigDecimal("50000"), i);
                // key = account → same partition per customer → ordered
                producer.send(new ProducerRecord<>("transactions", account, event.toJson()));
            }
            producer.flush();   // wait for all batches to be acknowledged
        }
        long ms = System.currentTimeMillis() - start;
        double rate = total / (ms / 1000.0);
        log.info(() -> String.format("Published %,d events in %,d ms (%.0f events/sec)",
                total, ms, rate));
    }
}

// ─── Would be in model/TxnEvent.java in a real project ───
class TxnEvent {
    private final String account;
    private final BigDecimal amount;
    private final long seq;
    TxnEvent(String account, BigDecimal amount, long seq) {
        this.account = account; this.amount = amount; this.seq = seq;
    }
    String toJson() {
        return "{\"account\":\"" + account + "\",\"amount\":" + amount + ",\"seq\":" + seq + "}";
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
